import type { Locale } from "./locales";

export type LocaleContent = {
  settings: Record<string, string>;
  features: { title: string; description: string; icon: string }[];
  benefits: { title: string; description: string }[];
  faqs: { question: string; answer: string }[];
  videoChapters: { chapter: string; title: string; description: string }[];
};

const ICONS = ["wallet", "users", "printer", "message", "devices"];

function build(
  settings: Record<string, string>,
  features: [string, string][],
  benefits: [string, string][],
  faqs: [string, string][],
  videoChapters: [string, string, string][],
): LocaleContent {
  return {
    settings,
    features: features.map(([title, description], i) => ({ title, description, icon: ICONS[i] ?? "sparkles" })),
    benefits: benefits.map(([title, description]) => ({ title, description })),
    faqs: faqs.map(([question, answer]) => ({ question, answer })),
    videoChapters: videoChapters.map(([chapter, title, description]) => ({ chapter, title, description })),
  };
}

